struct fade_vtable
{
    char padding[0x60];
    short adjustment;
    short reserved;
    void (*change_fade)(void *, bool, bool, float);
};

struct menu_vtable
{
    char padding[0x4c];
    short adjustment;
    short reserved;
    void (*change_fade)(void *, bool, bool, float);
};

struct fade_item
{
    fade_vtable *vtable;
};

struct menu_item
{
    menu_vtable *vtable;
};

struct PanelQuad
{
    void ChangeFade(bool start, bool fade_in, float time);
};

__asm__(".equ ChangeFade__9PanelQuadbT1f, 0x0014D078");

class BeachFrontEnd
{
    char padding0[0x4c];
    fade_item *main_item;
    char padding1[0x7fc];
    int selection;
    char padding2[0x14];
    fade_item *headers[3];
    char padding3[0xc];
    menu_item *entries[3][5];
    char padding4[0x53c];
    PanelQuad *fade_quads[2][9];
    char padding5[0x8];
    PanelQuad *extra_quad0;
    PanelQuad *extra_quad1;
    char padding6[0xf8];
    int enabled;
    int detailed;

public:
    void StartFrontendFade();
};

static void change_fade(fade_item *item)
{
    fade_vtable *table = item->vtable;
    table->change_fade((char *)item + table->adjustment, true, true, 1.0f);
}

static void change_fade(menu_item *item)
{
    menu_vtable *table = item->vtable;
    table->change_fade((char *)item + table->adjustment, true, true, 1.0f);
}

void BeachFrontEnd::StartFrontendFade()
{
    if (enabled)
    {
        if (detailed)
        {
            for (int i = 0; i < 3; ++i)
            {
                change_fade(headers[i]);
                for (int j = 0; j < 5; ++j)
                    if (entries[selection][i])
                        change_fade(entries[i][j]);
            }

            int row = entries[selection][0] != 0;
            for (int i = 0; i < 9; ++i)
                fade_quads[row][i]->ChangeFade(true, true, 1.0f);

            extra_quad0->ChangeFade(true, true, 1.0f);
            extra_quad1->ChangeFade(true, true, 1.0f);
        }

        change_fade(main_item);
    }
}
